const enabled = flow.get('client_automation_enabled');
if (enabled === false) return null;

// Cancel any pending shutdown
flow.set('shutdown_deadline', null);

const now = new Date();
const timestamp = now.toISOString();
const requestId = `boot-${Date.now()}`;

// Log the event
const activityLog = flow.get('activity_log') || [];
activityLog.unshift({
    timestamp: timestamp,
    action: 'Boot',
    type: 'wol',
    trigger: 'First client online',
    status: 'sent'
});
if (activityLog.length > 50) activityLog.pop();
flow.set('activity_log', activityLog);

flow.set('last_command', {
    action: "Boot",
    timestamp: timestamp,
    details: "First client online (WOL)"
});

flow.set('last_boot_timestamp', now.getTime());

// Format according to MQTT protocol
msg.payload = {
    action: "boot",
    method: "wol",
    timestamp: timestamp,
    request_id: requestId
};

node.status({fill: "green", shape: "dot", text: "Sending WOL"});
return msg;

const enabled = flow.get('client_automation_enabled');
if (enabled === false) return null;

// Set shutdown deadline (5 minutes grace period)
const GRACE_SECONDS = 300;
const deadline = new Date(Date.now() + GRACE_SECONDS * 1000).toISOString();
flow.set('shutdown_deadline', deadline);

const now = new Date().toISOString();

// Log the event
const activityLog = flow.get('activity_log') || [];
activityLog.unshift({
    timestamp: now,
    action: 'Grace Period',
    type: 'countdown',
    trigger: 'Last client offline',
    status: 'started',
    countdown: GRACE_SECONDS
});
if (activityLog.length > 50) activityLog.pop();
flow.set('activity_log', activityLog);

flow.set('last_command', {
    action: "Grace Period",
    timestamp: now,
    details: "Shutdown scheduled (last client offline)"
});

node.status({fill: "yellow", shape: "ring", text: "Grace period started"});
return msg;

const now = new Date();
const deadline = flow.get('shutdown_deadline');
const metadata = flow.get('status_metadata_dell_t310_status') || { currentState: 'unknown' };
const serverState = (metadata.currentState || 'unknown').toLowerCase();
const lastReported = metadata.lastReportedMs ? (now.getTime() - metadata.lastReportedMs) / 1000 : 9999;

const clients = flow.get('clients') || {};
const clientCount = Object.keys(clients).length;
const automationEnabled = flow.get('client_automation_enabled') !== false;
const activityLog = flow.get('activity_log') || [];

// Boot/Shutdown command cooldown (5 minutes)
const COMMAND_COOLDOWN_MS = 5 * 60 * 1000;
const lastBootTime = flow.get('last_boot_timestamp') || 0;
const lastShutdownTime = flow.get('last_shutdown_timestamp') || 0;
const timeSinceLastBoot = now.getTime() - lastBootTime;
const timeSinceLastShutdown = now.getTime() - lastShutdownTime;

// --- Part 1: Status Watchdog ---
let unknownDuration = context.get('unknown_duration') || 0;

if (serverState === 'unknown' || lastReported > 45) {
    unknownDuration += 1;
    context.set('unknown_duration', unknownDuration);

    if (unknownDuration >= 60 && timeSinceLastBoot > COMMAND_COOLDOWN_MS) {
        context.set('unknown_duration', 0);
        const timestamp = now.toISOString();
        const requestId = `recovery-boot-${Date.now()}`;

        // Log the recovery event
        activityLog.unshift({
            timestamp: timestamp,
            action: 'Recovery Boot',
            type: 'wol',
            trigger: 'Health lost for 60s',
            status: 'sent'
        });
        if (activityLog.length > 50) activityLog.pop();
        flow.set('activity_log', activityLog);

        flow.set('last_command', {
            action: "Recovery Boot",
            timestamp: timestamp,
            details: "Server health lost for 60s (WOL)"
        });

        flow.set('last_boot_timestamp', now.getTime());

        const bootMsg = {
            payload: {
                action: 'boot',
                method: 'wol',
                timestamp: timestamp,
                request_id: requestId
            }
        };

        node.warn("Watchdog recovery triggered (Health checks lost)");
        node.send([bootMsg, null, { payload: "refresh" }]);
        return null;
    }
} else {
    context.set('unknown_duration', 0);
}

// --- Part 2: Client Needs Server (Smart Wake-up) ---
// If clients are connected but server is down/unknown, wake it up
if (automationEnabled && clientCount > 0 && timeSinceLastBoot > COMMAND_COOLDOWN_MS) {
    const serverIsDown = (serverState === 'offline' || serverState === 'unknown' || serverState === 'error');

    if (serverIsDown) {
        const timestamp = now.toISOString();
        const requestId = `client-boot-${Date.now()}`;

        // Log the boot event
        activityLog.unshift({
            timestamp: timestamp,
            action: 'Boot',
            type: 'wol',
            trigger: `${clientCount} client(s) need server`,
            status: 'sent'
        });
        if (activityLog.length > 50) activityLog.pop();
        flow.set('activity_log', activityLog);

        flow.set('last_command', {
            action: "Boot",
            timestamp: timestamp,
            details: `Clients connected, server ${serverState} (WOL)`
        });

        flow.set('last_boot_timestamp', now.getTime());

        const bootMsg = {
            payload: {
                action: 'boot',
                method: 'wol',
                timestamp: timestamp,
                request_id: requestId
            }
        };

        node.status({fill: "green", shape: "dot", text: `Booting for ${clientCount} client(s)`});
        node.send([bootMsg, null, { payload: "refresh" }]);
        return null;
    }
}

// --- Part 3: Idle Server Monitor (Reactive Shutdown) ---
if (automationEnabled && serverState === 'online' && clientCount === 0 && !deadline) {
    const GRACE_SECONDS = 300;
    const newDeadline = new Date(Date.now() + GRACE_SECONDS * 1000).toISOString();
    flow.set('shutdown_deadline', newDeadline);

    const timestamp = now.toISOString();
    activityLog.unshift({
        timestamp: timestamp,
        action: 'Grace Period',
        type: 'countdown',
        trigger: 'Server up but idle',
        status: 'started',
        countdown: GRACE_SECONDS
    });
    if (activityLog.length > 50) activityLog.pop();
    flow.set('activity_log', activityLog);

    flow.set('last_command', {
        action: "Grace Period",
        timestamp: timestamp,
        details: "Auto-shutdown (Server up but idle)"
    });

    node.status({fill: "yellow", shape: "ring", text: "Idle grace started"});
    node.send([null, null, { payload: "refresh" }]);
    return null;
}

// --- Part 3: Shutdown Grace Countdown ---
if (deadline) {
    // Safety: Cancel shutdown if clients are present
    if (clientCount > 0) {
        flow.set('shutdown_deadline', null);
        const timestamp = now.toISOString();

        activityLog.unshift({
            timestamp: timestamp,
            action: 'Cancelled',
            type: 'abort',
            trigger: 'Client connected',
            status: 'cancelled'
        });
        if (activityLog.length > 50) activityLog.pop();
        flow.set('activity_log', activityLog);

        flow.set('last_command', {
            action: "Cancelled",
            timestamp: timestamp,
            details: "Shutdown aborted (Client connected)"
        });

        node.status({fill: "green", shape: "dot", text: "Shutdown cancelled"});
        node.send([null, null, { payload: "refresh" }]);
        return null;
    }

    const target = new Date(deadline);
    const remaining = Math.floor((target - now) / 1000);

    if (remaining <= 0) {
        // EXECUTE SHUTDOWN
        flow.set('shutdown_deadline', null);
        const timestamp = now.toISOString();
        const requestId = `shutdown-${Date.now()}`;

        activityLog.unshift({
            timestamp: timestamp,
            action: 'Shutdown',
            type: 'graceful',
            trigger: 'Grace period expired',
            status: 'executed'
        });
        if (activityLog.length > 50) activityLog.pop();
        flow.set('activity_log', activityLog);

        flow.set('last_command', {
            action: "Shutdown",
            timestamp: timestamp,
            details: "Graceful shutdown executed"
        });

        flow.set('last_shutdown_timestamp', now.getTime());

        // Format according to MQTT protocol
        const shutdownMsg = {
            payload: {
                action: 'shutdown',
                type: 'graceful',
                timeout: 300,
                timestamp: timestamp,
                request_id: requestId
            }
        };

        node.status({fill: "red", shape: "dot", text: "Executing shutdown"});
        node.send([null, shutdownMsg, { payload: "refresh" }]);
        return null;
    }

    node.status({fill: "blue", shape: "dot", text: `${remaining}s remaining`});
    node.send([null, null, { payload: "refresh" }]);
    return null;
}

if (serverState === 'unknown' || lastReported > 30) {
    node.status({fill: "grey", shape: "ring", text: `Health Lost: ${unknownDuration}s`});
    node.send([null, null, { payload: "refresh" }]);
    return null;
}

return null;

const newState = msg.payload;
const oldState = flow.get('client_automation_enabled');
flow.set('client_automation_enabled', newState);

const now = new Date().toISOString();
const activityLog = flow.get('activity_log') || [];

activityLog.unshift({
    timestamp: now,
    action: newState ? 'Automation Enabled' : 'Automation Disabled',
    type: 'config',
    trigger: 'User action',
    status: 'applied'
});
if (activityLog.length > 50) activityLog.pop();
flow.set('activity_log', activityLog);

node.status({fill: newState ? "green" : "red", shape: "ring", text: newState ? "AUTO" : "MANUAL"});
return msg;

const clients = flow.get('clients') || {};
const lastCommand = flow.get('last_command') || {
    action: "None",
    timestamp: "--",
    details: "No commands sent yet"
};
const automationEnabled = flow.get('client_automation_enabled');
const deadline = flow.get('shutdown_deadline');
const activityLog = flow.get('activity_log') || [];

const metadataKey = "status_metadata_dell_t310_status";
let metadata = flow.get(metadataKey) || {
    lastReportedMs: null,
    lastChangedMs: null,
    previousState: "Unknown",
    currentState: "Unknown"
};

// REMOVED: Health monitor logic that was conflicting with MQTT status updates
// The MQTT status publisher (via dell/t310/status topic) is now the single source of truth
// for server state. This prevents conflicting state updates between 'up'/'down' (health)
// and 'online'/'offline'/'unknown' (IPMI status).

let countdown = null;
if (deadline) {
    const remaining = Math.max(0, Math.floor((new Date(deadline) - new Date()) / 1000));
    const mins = Math.floor(remaining / 60);
    const secs = remaining % 60;
    countdown = `${mins}:${secs.toString().padStart(2, '0')}`;
}

// Calculate command cooldown status
const COMMAND_COOLDOWN_MS = 5 * 60 * 1000;
const lastBootTime = flow.get('last_boot_timestamp') || 0;
const lastShutdownTime = flow.get('last_shutdown_timestamp') || 0;
const nowMs = Date.now();
const timeSinceLastBoot = nowMs - lastBootTime;
const timeSinceLastShutdown = nowMs - lastShutdownTime;

let cooldownInfo = null;
if (timeSinceLastBoot > 0 && timeSinceLastBoot < COMMAND_COOLDOWN_MS) {
    const remaining = Math.floor((COMMAND_COOLDOWN_MS - timeSinceLastBoot) / 1000);
    cooldownInfo = {
        type: 'boot',
        remaining_seconds: remaining,
        message: `Boot cooldown: ${Math.floor(remaining / 60)}:${(remaining % 60).toString().padStart(2, '0')}`
    };
} else if (timeSinceLastShutdown > 0 && timeSinceLastShutdown < COMMAND_COOLDOWN_MS) {
    const remaining = Math.floor((COMMAND_COOLDOWN_MS - timeSinceLastShutdown) / 1000);
    cooldownInfo = {
        type: 'shutdown',
        remaining_seconds: remaining,
        message: `Shutdown cooldown: ${Math.floor(remaining / 60)}:${(remaining % 60).toString().padStart(2, '0')}`
    };
}

msg.payload = {
    client_count: Object.keys(clients).length,
    last_command: lastCommand,
    automation_enabled: automationEnabled !== false,
    shutdown_countdown: countdown,
    cooldown_info: cooldownInfo,
    metadata: metadata,
    activity_log: activityLog.slice(0, 8),
    timestamp: new Date().toISOString()
};

return msg;
